import re
def entries(path='explorations/coordinator/FACTS.md'):
    out=[]
    for l in open(path):
        if l.startswith('- F-'):
            m=re.match(r'- (F-\d+) ',l); out.append((m.group(1),l.rstrip('\n')))
    return out
def sentences(line):
    # split on '. ' / '; '? no: only '. ' outside backticks and parens, followed by uppercase/backtick/digit
    s=[];cur='';bt=False;par=0;i=0
    while i<len(line):
        ch=line[i];cur+=ch
        if ch=='`': bt=not bt
        elif not bt and ch=='(': par+=1
        elif not bt and ch==')': par=max(0,par-1)
        elif not bt and par==0 and ch in '.' and i+2<len(line) and line[i+1]==' ' and re.match(r'[A-Z`"0-9]',line[i+2]):
            prev=cur[-5:]
            if not re.search(r'(e\.g|i\.e|cf|vs|\bp|\bl|No|\bS|ll|\bal)\.$',prev):
                s.append(cur.strip());cur=''
        elif not bt and line[i:i+2]=='**' and cur.strip().startswith('- F-') and cur.count('**')==1:
            pass
        i+=1
    if cur.strip(): s.append(cur.strip())
    # separate title
    if s and s[0].startswith('- F-'):
        m=re.match(r'(- F-\d+ \*\*.*?\*\*)\s*(.*)$',s[0])
        if m: s=[m.group(1)]+([m.group(2)] if m.group(2) else [])+s[1:]
    return s
TEST_START=re.compile(r'^(Gated\b|Tests?\b:?|No (gated )?(test|program)|Plain tests gate|No test)',re.I)
def test_sentences(sents):
    return [x for x in sents[1:] if TEST_START.match(x) and not x.startswith('Test ')] 
